INSERT INTO public.content_items VALUES ('ade8ed3f-677e-4374-9b1e-392784439f90', 'temoignage', 'temoignage-kotto', 'Mireille Kotto', true, 11, '{"id": "temoignage-kotto", "role": "Fondatrice & Gérante", "text": "Arckaton a résolu le cauchemar des fausses captures d''écran de transfert. Désormais, l''argent est sur notre compte avant même que le livreur ne charge le colis. C''est le jour et la nuit.", "author": "Mireille Kotto", "company": "Maison Kotto, Bastos", "metrics": "+337% de conversion • 12.4M FCFA encaissés • 0 impayé"}', '2026-10-01 00:34:40.705953+00', '2026-10-01 00:34:40.705953+00');
INSERT INTO public.content_items VALUES ('30ae7aab-dbf9-47ce-9e09-4dba5b9c211e', 'temoignage', 'temoignage-districash', 'Direction Générale', true, 12, '{"id": "temoignage-districash", "role": "Directeur des Opérations", "text": "Nos gérants ne perdent plus aucune vente lors des coupures de courant. L''inventaire est passé de 3 heures à 12 minutes chrono. ARKA-PME a sauvé notre rentabilité.", "author": "Direction Générale", "company": "Districash Nord, Douala", "metrics": "Inventaire en 12 min • 12 000 références • Mode hors-ligne"}', '2026-10-01 00:34:40.705953+00', '2026-10-01 00:34:40.705953+00');
